def cl(x):
 if isinstance(x,str):return x.replace('加工','প্রক্রিয়াকরণ').replace('仕様','নির্ধারিত বৈশিষ্ট্য')
 if isinstance(x,(list,tuple)):return[cl(a)for a in x]
 return x
